<?php
require_once __DIR__.'/../includes/bootstrap.php';$active='pr';$embedded=isset($_GET['embed']);
if(isset($_GET['ppmp_items'])){$id=(int)$_GET['ppmp_items'];$items=db_all('SELECT pi.*,i.item_code,p.fund_source,pi.planned_quantity-COALESCE((SELECT SUM(ri.quantity_requested) FROM procurement_request_items ri JOIN procurement_requests r ON r.id=ri.request_id WHERE ri.ppmp_item_id=pi.id AND r.status<>"REJECTED"),0) remaining FROM procurement_ppmp_items pi JOIN items i ON i.id=pi.item_id JOIN procurement_ppmp p ON p.id=pi.ppmp_id WHERE pi.ppmp_id=? AND p.status="APPROVED"',[$id]);header('Content-Type: application/json');echo json_encode($items);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf_token();$action=$_POST['action']??'';try{
 if($action==='create'){$purpose=trim((string)($_POST['purpose']??''));if($purpose==='')throw new RuntimeException('Purpose is required.');$ppmpId=(int)$_POST['ppmp_id'];$ppmp=db_one('SELECT * FROM procurement_ppmp WHERE id=? AND status="APPROVED"',[$ppmpId]);if(!$ppmp)throw new RuntimeException('Select an approved PPMP.');$date=$_POST['request_date']??date('Y-m-d');$no=procurement_number('PR','procurement_requests','pr_no',(int)date('Y',strtotime($date)));db()->beginTransaction();$sources=db_all('SELECT * FROM procurement_ppmp_items WHERE ppmp_id=? ORDER BY id FOR UPDATE',[$ppmpId]);if(!$sources)throw new RuntimeException('The approved PPMP has no items.');if((int)db_value('SELECT COUNT(*) FROM procurement_requests WHERE ppmp_id=? AND status<>"REJECTED"',[$ppmpId])>0)throw new RuntimeException('This approved PPMP already has an active Purchase Request.');db_statement('INSERT INTO procurement_requests(pr_no,ppmp_id,request_date,department_id,fund_cluster,responsibility_center,charged_to,purpose,status,requested_by,expected_delivery_date,po_number,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$no,$ppmpId,$date,$ppmp['department_id'],trim((string)$_POST['fund_cluster']),trim((string)$_POST['responsibility_center']),(string)($ppmp['fund_source']??''),$purpose,'AWAITING QUOTATION',current_user()['full_name'],$_POST['expected_delivery_date']?:null,trim((string)$_POST['po_number']),current_user()['id']]);$requestId=(int)db()->lastInsertId();foreach($sources as$source){$qty=(int)$source['planned_quantity'];if($qty<=0)throw new RuntimeException('Every PPMP item must have a valid quantity.');db_statement('INSERT INTO procurement_request_items(request_id,ppmp_item_id,item_id,unit,item_description,quantity_requested,unit_cost,procurement_status) VALUES(?,?,?,?,?,?,?,"AWAITING QUOTATION")',[$requestId,$source['id'],$source['item_id'],$source['unit'],$source['item_description'],$qty,$source['unit_cost']]);}db()->commit();set_flash('success','Purchase Request '.$no.' was created successfully. Its items are now awaiting quotation.');}
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();set_flash('danger',safe_error_message($e));}redirect($action==='create'?'ppmp.php':'purchase_requests.php');}
$ppmps=db_all('SELECT p.id,p.ppmp_no,p.fiscal_year,d.department_name FROM procurement_ppmp p LEFT JOIN departments d ON d.id=p.department_id WHERE p.status="APPROVED" AND NOT EXISTS (SELECT 1 FROM procurement_requests r WHERE r.ppmp_id=p.id AND r.status<>"REJECTED") ORDER BY p.id DESC');
procurement_header('Purchase Requests','pr','Create Purchase Requests from approved PPMP items.');?>
<link rel="stylesheet" href="../assets/ppmp.css"><style>.pr-create{padding:0;overflow:hidden}.pr-form-dialog #prForm .grid{grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px 24px;align-items:end}.pr-form-dialog #prForm .grid label{min-width:0;font-size:14px;line-height:1.6;font-weight:700;color:#213f52}.pr-form-dialog #prForm .grid input,.pr-form-dialog #prForm .grid select,.pr-form-dialog #prForm .grid textarea{min-width:0;min-height:48px;margin-top:9px;padding:12px 14px;font:inherit;font-size:15px;font-weight:400;color:#173b50;border:1px solid #b5c9d5;border-radius:8px}.pr-form-dialog #prForm .grid textarea{min-height:82px;resize:vertical}.pr-form-dialog #prForm .grid .wide{grid-column:1/-1}.pr-items-section{background:#fbfdfe}.pr-items-section .table-wrap{border:1px solid #dce7ed;border-radius:8px;background:#fff}.pr-items-section .table{min-width:980px}.pr-items-section .table th{padding:14px 12px;background:#edf4f7;color:#304e62;font-size:13px}.pr-items-section .table td{padding:13px 12px;vertical-align:middle}.pr-qty[readonly]{background:#edf3f6;color:#304e62;cursor:not-allowed}.pr-form-dialog .ppmp-cart-summary{margin-right:auto}@media(max-width:600px){.pr-form-dialog #prForm .grid .wide{grid-column:auto}}<?php if($embedded):?>.proc-sidebar,.proc-top,.pr-create>.panel-head{display:none!important}.proc-shell{display:block!important}.proc-shell main{margin:0!important;padding:0!important;min-height:0!important}.pr-create{border:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important}.pr-form-dialog{width:100%!important;max-width:none!important;height:100vh!important;max-height:100vh!important;border:0!important;border-radius:0!important;box-shadow:none!important}<?php endif;?></style>
<section class="panel pr-create ppmp-create"><div class="panel-head ppmp-create-head"><div><span class="ppmp-eyebrow">PURCHASE REQUEST</span><h2>Create Purchase Request</h2><p>Prepare a request using quantities from an approved PPMP.</p></div><button class="btn" type="button" id="toggle">+ New PR</button></div><dialog id="prDialog" class="ppmp-form-dialog pr-form-dialog" aria-labelledby="prDialogTitle"><form method="post" id="prForm"><div class="ppmp-back-row"><h2 id="prDialogTitle">Create Purchase Request</h2></div><?=csrf_field()?><input type="hidden" name="action" value="create"><section class="ppmp-form-section" aria-labelledby="prDetailsHeading"><div class="ppmp-section-heading"><span class="ppmp-step">01</span><div><h3 id="prDetailsHeading">Request details</h3><p>Select the approved plan and enter the request information.</p></div></div><div class="grid"><label>Approved PPMP <span class="ppmp-required">*</span><select name="ppmp_id" id="ppmp" required><option value="">Select PPMP</option><?php foreach($ppmps as$p):?><option value="<?=$p['id']?>"><?=e($p['ppmp_no'].' — '.($p['department_name']??'CSSR'))?></option><?php endforeach;?></select></label><label>Request Date <span class="ppmp-required">*</span><input type="date" name="request_date" value="<?=date('Y-m-d')?>" required></label><label>Fund Cluster<input name="fund_cluster"></label><label>Responsibility Center Code<input name="responsibility_center"></label><label>Charged To<input name="charged_to"></label><label>PO Number<input name="po_number"></label><label>Expected Delivery<input type="date" name="expected_delivery_date"></label><label class="wide">Purpose <span class="ppmp-required">*</span><textarea name="purpose" rows="2" required></textarea></label></div></section><section class="ppmp-form-section pr-items-section" aria-labelledby="prItemsHeading"><div class="ppmp-section-heading"><span class="ppmp-step">02</span><div><h3 id="prItemsHeading">PPMP items</h3><p>Items, quantities, and prices are copied automatically from the approved PPMP.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Unit</th><th>Item Description</th><th>Qty</th><th>Unit Cost</th><th>Total</th></tr></thead><tbody id="available"><tr><td colspan="5" class="muted">Select an approved PPMP.</td></tr></tbody></table></div></section><footer class="ppmp-form-footer"><div class="ppmp-cart-summary" role="status" aria-live="polite"><div><span>Total Items</span><strong id="prItemCount">0</strong></div><div><span>Total Amount</span><strong id="prTotal">₱0.00</strong></div></div><div class="actions"><button type="button" class="btn light" id="cancel">Back</button><button class="btn green" type="submit">Save Purchase Request</button></div></footer></form></dialog></section>
<script>const dialog=document.getElementById('prDialog'),form=document.getElementById('prForm'),body=document.getElementById('available'),count=document.getElementById('prItemCount'),total=document.getElementById('prTotal');let ppmpItems=[];document.getElementById('toggle').onclick=()=>dialog.showModal();document.getElementById('cancel').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.getElementById('toggle').focus());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});document.getElementById('ppmp').onchange=async function(){if(!this.value){ppmpItems=[];body.innerHTML='<tr><td colspan="5" class="muted">Select an approved PPMP.</td></tr>';sync();return}body.innerHTML='<tr><td colspan="5" class="muted">Loading approved PPMP items...</td></tr>';ppmpItems=await fetch('?ppmp_items='+this.value).then(r=>r.json());body.innerHTML=ppmpItems.length?ppmpItems.map(item=>{const quantity=Number(item.planned_quantity),unitCost=Number(item.unit_cost),lineTotal=quantity*unitCost;return `<tr><td>${item.unit||''}</td><td><strong>${item.item_description}</strong></td><td>${quantity}</td><td>₱${unitCost.toFixed(2)}</td><td>₱${lineTotal.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>`}).join(''):'<tr><td colspan="5" class="muted">This PPMP has no items.</td></tr>';sync()};function sync(){const amount=ppmpItems.reduce((sum,item)=>sum+(Number(item.planned_quantity)*Number(item.unit_cost)),0);count.textContent=String(ppmpItems.length);total.textContent='₱'+amount.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}form.onsubmit=e=>{if(!form.checkValidity()){e.preventDefault();form.reportValidity();return}if(!ppmpItems.length){e.preventDefault();alert('The selected PPMP has no items.')}};if(new URLSearchParams(location.search).get('new')==='1')dialog.showModal();</script>
<?php if($embedded):?><script>document.getElementById('cancel').onclick=()=>parent.postMessage('close-pr-popup',location.origin);</script><?php endif;?>
<script>(()=>{const ppmp=document.getElementById('ppmp'),chargedTo=document.querySelector('#prForm [name="charged_to"]');chargedTo.readOnly=true;chargedTo.setAttribute('aria-label','Charged To, copied from PPMP Fund Source');chargedTo.style.background='#edf3f6';ppmp.addEventListener('change',async function(){chargedTo.value='';if(!this.value)return;const items=await fetch('?ppmp_items='+encodeURIComponent(this.value)).then(response=>response.json());chargedTo.value=items[0]?.fund_source||''})})();</script>
